from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parent.parent))
from rendu import outils

B,p,c,h,w,table,liste,save=outils(1,10)
t=h('10.a — Si une menace apparaît, le parcours change immédiatement')
t+=liste([
('Si une douleur d’effort évoque une rhabdomyolyse, le bilan apprécie l’atteinte musculaire et ses complications ; une menace rénale sévère ou électrolytique relève de la priorité 🚩E1.',['p83-rhabdo-clinique','p83-rhabdo-menace']),
('Si une douleur traumatique est disproportionnée ou accentuée par le mouvement passif, le clinicien recherche le syndrome des loges aigu ; une décompression suit immédiatement le diagnostic.',['p83-boast-loges-0','p83-boast-loges-3']),
('Si une alarme sphinctérienne ou un déficit moteur accompagne le tableau rachidien, une imagerie sans attendre et un avis neurochirurgical sont obtenus.',['pa17-lomb22-queue','pa17-lomb22-urgence']),
('Si une artérite à cellules géantes est fortement suspectée, les glucocorticoïdes commencent sans délai pendant la confirmation ; la simple suspicion justifie un avis spécialisé rapide.',['p83-pmr-acg-eular2026']),
('Si une douleur thoracique, une toux ou une dyspnée survient après needling, une orientation aux urgences recherche un pneumothorax.',['dvs83-pneumothorax'])])
t+=h('10.b — Si le tableau reste régional, la chronologie dirige le premier embranchement')
t+=table(['Situation constatée','Étape suivante','Décision reliée'],[
[p('Un choc direct précède immédiatement la douleur.','p83-doms-contusion-clinique'),p('L’examen décrit l’hématome, la mobilité active et les signes de menace.','p83-doms-contusion-clinique','p83-boast-loges-0'),p('La filière traumatique remplace une attribution d’emblée au point gâchette.','p83-doms-contusion-clinique','p83-boast-loges-3')],
[p('Les courbatures et la raideur apparaissent après l’activité.','p83-doms-contusion-clinique'),p('La chronologie et la gravité sont confrontées au contexte d’effort et aux symptômes associés.','p83-doms-contusion-clinique','p83-rhabdo-clinique'),p('Une suspicion de rhabdomyolyse fait poursuivre le bilan médical plutôt que retenir automatiquement des DOMS.','p83-rhabdo-clinique','p83-rhabdo-menace')],
[p('Une posture ou un usage soutenu entretient une douleur régionale.','c83-17','c83-19'),p('Le clinicien recherche la bande tendue et le point qui reproduit une sensation familière.','p83-myofascial-fibro','eu83-actif'),p('Une concordance clinique permet de construire un programme multimodal adapté aux facteurs présents.','c83-25','barbero83-resume')],
[p('Une irradiation évoque une atteinte radiculaire.','c83-9','c83-30'),p('L’examen neurologique précise réflexes, force et sensibilité, puis oriente les examens utiles.','c83-30'),p('Un résultat concordant avec une autre atteinte ouvre son parcours spécifique, avec urgence si alarme.','c83-30','pa17-lomb22-urgence')]])
t+=h('10.c — Si le point est latent ou si la plainte est diffuse, l’interprétation reste ouverte')
t+=p('Si le point palpé ne reproduit pas une expérience familière, le clinicien précise sa pertinence au lieu de le qualifier automatiquement d’actif. Les points latents observés chez des personnes sans plainte justifient cette prudence d’interprétation.','eu83-actif','eu83-phenotypes')
t+=p('Si les douleurs sont généralisées et chroniques avec fatigue ou sommeil non réparateur, la caractérisation d’une fibromyalgie et la recherche d’affections associées deviennent pertinentes. Une faiblesse objective ou une CK anormale fait cependant poursuivre le bilan musculaire ou neurologique.','p83-myofascial-fibro','dgn83-laboratoire')
t+=p('Si un contexte thyroïdien ou médicamenteux est présent, le bilan recherche cette contribution. Les mécanismes peuvent coexister ; le programme ne se limite donc pas à l’une des étiquettes.','p83-hypothyroidie','p83-statine-frequence','nice83-vie')
t+=h('10.d — Si le diagnostic est retenu, le traitement et le suivi restent actifs')
t+=p('Si la concordance clinique soutient le syndrome myofascial, l’éducation, l’activité adaptée et les interventions locales éventuelles sont réunies dans un plan multimodal. Le suivi porte sur les symptômes et la fonction plutôt que sur la seule disparition d’un point à la pression.','barbero83-resume','eu83-multimodal')
t+=p('Si la douleur s’inscrit dans une forme chronique primaire, les recommandations NICE de ce cadre guident notamment l’exercice et les thérapies psychologiques adaptées. Cette décision reste distincte du traitement d’une cause secondaire identifiée.','nice83-definition','nice83-physique','nice83-psycho')
t+=p('Si la présentation change, le diagnostic est réévalué. Si le bénéfice d’un traitement est bref, le plan recherche les facteurs de maintien et les possibilités d’autogestion, au lieu d’enchaîner uniquement des interventions passives.','nice83-vie','eu83-multimodal')
save(t)

B,p,c,h,w,table,liste,save=outils(1,11)
t=h('11.A — Le but associe symptômes, fonction et autonomie')
t+=p('La revue suisse de Barbero et ses collègues relie le traitement des points gâchettes à la douleur et à l’incapacité ; elle propose un programme multimodal associant notamment techniques manuelles et dry needling. La cible clinique dépasse donc une modification immédiate du point palpable.','barbero83-resume')
t+=p('Le plan fixe avec la personne les activités devenues difficiles et les changements utiles dans la vie quotidienne. Le suivi peut ainsi confronter l’évolution de la plainte, de la mobilité, du travail et du sommeil aux objectifs choisis.','nice83-evaluation','nice83-vie','eu83-multimodal')
t+=p('Une amélioration brève après une technique passive est distinguée d’un bénéfice durable sur la participation. Les données de court terme soutiennent donc son intégration à des moyens actifs et à une gestion plus autonome des symptômes.','eu83-limite-effet','eu83-multimodal')
t+=h('11.B — La sécurité et les facteurs de maintien organisent les moyens')
a=w('Urgence — conduite chronologique',[
('Le clinicien interrompt le parcours de traitement local devant une menace aiguë et organise la réponse au mécanisme suspecté. Le guide suisse exclut le dry needling de toute urgence aiguë ou vitale.',['dvs83-infections']),
('Une suspicion de rhabdomyolyse est évaluée pour ses complications rénales et électrolytiques. Leur prévention et leur prise en charge constituent le centre du traitement de cette branche.',['p83-rhabdo-menace']),
('Une douleur post-traumatique disproportionnée ou provoquée au mouvement passif fait rechercher le syndrome des loges aigu. La décompression chirurgicale suit immédiatement son diagnostic.',['p83-boast-loges-0','p83-boast-loges-3']),
('Les alarmes de queue de cheval ou un déficit moteur justifient une imagerie sans attendre avec avis neurochirurgical. La prise en charge ne dépend donc pas de la disparition d’un point musculaire sensible.',['pa17-lomb22-queue','pa17-lomb22-urgence']),
('Après needling, les signes évocateurs de pneumothorax imposent une orientation aux urgences. Un saignement important ou une infection suspectée demande également un avis médical selon les signes.',['dvs83-pneumothorax','dvs83-hemorragie','dvs83-infection-apres'])])
t+=p('La fenêtre '+a+' hiérarchise la conduite. Lorsque ces menaces ont reçu la réponse appropriée, le traitement du tableau myofascial peut s’organiser selon la concordance clinique et les facteurs présents.','dvs83-infections','barbero83-resume')
t+=h('11.B.1 — L’éducation et l’activité donnent une continuité au soin local')
t+=p('Le clinicien explique le lien possible entre le muscle, la sensibilité et la fonction sans présenter la douleur comme la mesure directe d’une lésion. La revue européenne propose cette cohérence du message pour soutenir une participation active au programme.','eu83-sensibilisation','eu83-multimodal','eu83-communication')
t+=p('Le programme peut associer activité graduée, exercice, stratégies d’autogestion, attention au sommeil et gestion du stress. Ces moyens répondent aux facteurs de maintien et aux limitations qui dépassent le foyer musculaire.','eu83-multimodal','c83-20','c83-22')
t+=p('Les exercices peuvent travailler mobilité, étirement, force, endurance ou coordination selon la situation. La fiche IASP décrit leur bénéfice modéré et les intègre à une prise en charge multimodale, plutôt qu’à un protocole identique pour tous les muscles.','iasp83-traitement')
t+=p('Pour une douleur chronique primaire chez une personne d’au moins16ans, NICE recommande un programme d’exercice supervisé en tenant compte des capacités, préférences et besoins. Le même cadre encourage le maintien d’une activité physique pour les bénéfices généraux à long terme.','nice83-physique')
t+=p('Dans ce cadre chronique primaire, une thérapie d’acceptation et d’engagement ou une thérapie cognitive et comportementale de la douleur peut être envisagée avec un professionnel formé. Cette option ne remplace pas le traitement d’une cause secondaire démontrée.','nice83-psycho','nice83-definition')
t+=h('11.B.2 — Les moyens manuels et le needling sont des options contextualisées')
t+=p('Les techniques de tissus mous, dont massage, relâchement par pression et autres approches manuelles, peuvent améliorer immédiatement la douleur. Le bénéfice recherché est ensuite relié à la reprise du mouvement et aux objectifs fonctionnels.','iasp83-traitement','eu83-multimodal')
t+=p('Le dry needling introduit une aiguille sans substance injectée ; il se distingue donc d’une injection locale. Son choix prend en compte les compétences du praticien, les risques et l’accord de la personne.','eu83-modes','dvs83-competences','dvs83-consentement')
t+=p('La revue européenne situe surtout les effets dans le court ou le moyen terme et décrit une hétérogénéité des résultats selon le territoire et les comparateurs. Ainsi, une technique utile à un patient ne devient pas une promesse universelle de guérison durable.','eu83-limite-effet','eu83-heterogene','eu83-comparateur')
a=w('Avant le dry needling : décision, sécurité et information',[
('Le guide suisse exige que le praticien soit formé dans la région traitée et connaisse les limites de la méthode. Le choix d’un autre moyen reste pertinent lorsque les conditions de sécurité ne sont pas réunies.',['dvs83-competences']),
('Les anticoagulants et les antiagrégants sont revus avec les antécédents de saignement. Leur interruption pour permettre le needling est interdite dans le guide suisse, qui distingue plusieurs groupes de traitements et de risques.',['dvs83-coagulation']),
('Les infections systémiques aiguës et les urgences ne sont pas traitées par cette méthode. Des altérations cutanées, une zone d’hématome ou la proximité d’implants modifient également les possibilités locales du geste.',['dvs83-infections','dvs83-locaux']),
('Le patient est informé de la sensation attendue, d’une possible secousse locale et des suites habituelles. Il dispose d’un signal pour interrompre la procédure et reçoit une information sur les complications possibles.',['dvs83-information']),
('L’asepsie implique du matériel stérile à usage unique et la désinfection de la peau avant chaque puncture. La connaissance des structures voisines et le temps nécessaire au geste participent à la prévention du risque.',['dvs83-information','dvs83-asepsie'])])
t+=p('La fenêtre '+a+' situe le geste dans un acte professionnel encadré. La présence d’un point actif et une demande de soulagement ne suffisent donc pas à contourner une contre-indication ou un refus.','dvs83-consentement','dvs83-infections','dvs83-locaux')
t+=h('11.B.3 — L’antalgie symptomatique reste distincte du traitement spécifique')
t+=p('Dafalgan® contient du paracétamol ; les formes orales citées disposent notamment d’indications pour les douleurs dorsales, les douleurs après blessures et d’autres douleurs faibles à modérées. Ce périmètre AIPS ne constitue pas une démonstration d’efficacité spécifique sur les points gâchettes.','aips-m83-dafalgan-indication','barbero83-resume')
t+=p('Les numéros Swissmedic47503,47505 et56318 ainsi que la mise à jour de juillet2026 sont lus dans l’information professionnelle. Les doses suivantes concernent ces formes et leurs limites, dans une décision d’antalgie symptomatique correspondant à une indication de notice.','aips-m83-dafalgan-numero','aips-m83-dafalgan-edition','aips-m83-dafalgan-indication')
rows=[
[p('Adulte de plus de40kg : comprimés effervescents à500mg.','aips-m83-dafalgan-posologie'),p('La prise orale est de500 à1\'000mg, après dissolution ; le médicament ne se mâche pas et ne s’avale pas sous forme de comprimé effervescent.','aips-m83-dafalgan-posologie'),p('L’intervalle adulte est de4 à8h ; le plafond est de4g par jour, à réduire selon les facteurs de risque.','aips-m83-dafalgan-posologie')],
[p('Adulte de plus de50kg : forme orale à1g.','aips-m83-dafalgan-posologie'),p('La prise est d’un comprimé de1g, effervescent dissous ou pelliculé avalé entier ; le sillon décoratif ne sert pas à réduire la dose.','aips-m83-dafalgan-posologie'),p('L’intervalle est de4 à8h et le plafond de4g par jour ; la forme à1g ne s’utilise pas chez une personne de moins de50kg.','aips-m83-dafalgan-posologie')],
[p('Clairance de créatinine de10 à50ml/min.','aips-m83-dafalgan-posologie'),p('Le plafond quotidien est de3000mg.','aips-m83-dafalgan-posologie'),p('L’intervalle minimal est de6heures et les autres facteurs imposant une réduction restent pris en compte.','aips-m83-dafalgan-posologie')],
[p('Clairance de créatinine inférieure à10ml/min.','aips-m83-dafalgan-posologie'),p('Le plafond quotidien est de2000mg.','aips-m83-dafalgan-posologie'),p('L’intervalle minimal est de8heures.','aips-m83-dafalgan-posologie')],
[p('Maladie hépatique chronique ou compensée, alcoolisme, dénutrition, déshydratation ou cachexie.','aips-m83-dafalgan-posologie'),p('La dose est réduite ou l’intervalle allongé, avec un plafond de2g par jour dans les situations décrites.','aips-m83-dafalgan-posologie'),p('Une atteinte hépatique sévère, une hépatite aiguë ou une maladie hépatique décompensée active contre-indique le médicament.','aips-m83-dafalgan-contreindications')]]
t+=table(['Situation et forme','Dose et voie AIPS','Intervalle, plafond ou limite'],rows)
t+=p('L’hypersensibilité au paracétamol, aux substances apparentées ou aux excipients, ainsi que la maladie de Gilbert, sont également des contre-indications. La vérification des médicaments associés recherche un cumul involontaire de paracétamol.','aips-m83-dafalgan-contreindications','aips-m83-dafalgan-posologie')
a=w('Enfant, grossesse, allaitement et personne âgée : limites de la notice',[
('Chez l’enfant, la dose dépend du poids et de la forme ; l’intervalle est de6 à8heures. Le plafond général de75mg/kg/jour ne permet pas de dépasser les plafonds plus bas des tableaux de notice.',['aips-m83-dafalgan-posologie']),
('Pour la forme effervescente à500mg, le plafond quotidien est de1,5g entre22 et30kg, et de2g entre30 et40kg. Jusqu’à12ans, l’utilisation continue sans consultation médicale est limitée à3jours.',['aips-m83-dafalgan-posologie']),
('Pendant la grossesse, le paracétamol peut être utilisé en cas de nécessité clinique, à la dose efficace la plus faible, pendant la durée la plus courte et avec la fréquence la plus basse possible.',['aips-m83-dafalgan-grossesse']),
('L’utilisation est considérée compatible avec l’allaitement, mais la notice demande de la prudence. Cette compatibilité n’est donc pas présentée comme une absence absolue de tout risque.',['aips-m83-dafalgan-grossesse']),
('L’âge seul ne demande normalement pas d’adaptation ; cependant, les facteurs associés, notamment rénaux, hépatiques et nutritionnels, peuvent imposer une réduction.',['aips-m83-dafalgan-posologie'])])
t+=p('La fenêtre '+a+' complète les doses par forme. Le médicament ne remplace toutefois ni la recherche d’une autre cause de douleur ni le travail fonctionnel du programme myofascial.','aips-m83-dafalgan-indication','barbero83-resume','eu83-multimodal')
t+=h('11.B.4 — Une douleur chronique primaire suit son propre cadre thérapeutique')
t+=p('NICE recommande de ne pas débuter, pour traiter une douleur chronique primaire, le paracétamol, les anti-inflammatoires, les opioïdes, les benzodiazépines ou plusieurs autres traitements énumérés dans cette recommandation. Ce cadre concerne une indication différente de l’antalgie symptomatique d’une cause secondaire contenue dans la notice suisse.','nice83-eviter','nice83-definition','aips-m83-dafalgan-indication')
t+=p('Si de tels médicaments sont déjà utilisés pour une douleur chronique primaire, NICE propose une revue partagée des bénéfices et des risques. Un changement tient également compte des difficultés de sevrage possibles ; il ne s’agit donc pas d’un arrêt brutal automatique.','nice83-reviser')
t+=p('Le choix d’une option de douleur chronique est relié au tableau complet et à la balance bénéfice-risque. Les moyens actifs et l’évaluation de la vie quotidienne restent ainsi essentiels même lorsqu’une intervention locale apporte un soulagement.','nice83-evaluation','nice83-vie','eu83-multimodal')
t+=h('11.C — Surveillance : bénéfice fonctionnel, sécurité et diagnostic restent suivis')
t+=p('Le suivi reprend les activités choisies, la distribution des symptômes et les facteurs de maintien. Une évolution différente de celle attendue ou de nouveaux signes conduit à réexaminer le diagnostic et les causes associées.','nice83-vie','c83-20','c83-22')
t+=p('Après needling, de petits hématomes et une douleur musculaire transitoire sont des réactions possibles. En revanche, douleur thoracique, dyspnée, saignement important ou signes d’infection sont analysés comme des complications potentielles avec la réponse appropriée.','dvs83-information','dvs83-pneumothorax','dvs83-hemorragie','dvs83-infection-apres')
t+=p('Le contrôle du traitement symptomatique porte sur le bénéfice, le cumul de prises et les facteurs qui limitent la dose. Une nouvelle atteinte rénale, hépatique ou une situation nutritionnelle défavorable impose donc une réévaluation de l’antalgie.','aips-m83-dafalgan-posologie','aips-m83-dafalgan-contreindications','nice83-reviser')
t+=h('11.D — Continuité et fin d’épisode : privilégier une activité plus autonome')
t+=p('Une réponse satisfaisante associe une fonction plus utile et une gestion des symptômes compatible avec la vie de la personne. Une simple amélioration immédiatement après une technique ne constitue donc pas le seul critère de fin de suivi.','eu83-multimodal','nice83-vie')
t+=p('La continuité organise les exercices, les adaptations d’activité et le recours au professionnel si le tableau change. Le volet social considère les contraintes d’emploi, de revenu, de logement et de soutien qui peuvent compliquer la mise en œuvre du plan.','eu83-multimodal','nice83-vie')
t+=p('Le patient reçoit, après une intervention invasive, les réactions habituelles et les signes qui demandent un avis. Le praticien documente les réactions et le consentement, puis adapte les moyens aux résultats obtenus et aux préférences de la personne.','dvs83-information','dvs83-competences','nice83-evaluation')
save(t)
